#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("NOOP\n");
        return 0;
    }
    int size = 0;
    long heap[1000];
    for (int i = 1; i < argc; i++) {
        char *endptr;
        long val = strtol(argv[i], &endptr, 10);
        if (endptr == argv[i]) {
            printf("ERR\n");
            return 0;
        }
        heap[size++] = val;
    }
    for (int i = 0; i < size; i++) {
        printf("INS %ld\n", heap[i]);
    }
    for (int i = 0; i < size; i++) {
        for (int j = i + 1; j < size; j++) {
            if (heap[i] > heap[j]) {
                long temp = heap[i];
                heap[i] = heap[j];
                heap[j] = temp;
            }
        }
    }
    printf("MIN %ld\n", heap[0]);
    return 0;
}
